class Point {

  int x;
  int y;

  Point(int x, int y) {
    this.x = x;
    this.y = y;
  }

  int sum() {
    return this.x + this.y;
  }
}

extension PointExt on Point {

  int scaled(int by) {
    return this.sum() * by;
  }

  int get doubledSum {
    return this.scaled(2);
  }

}

class Foo {

  void test(int a) {
    var p = Point(a, 1);
    print('scaled: ${p.scaled(3)}');
    print('doubledSum: ${p.doubledSum}');
  }
}
